'use strict';
// AI: below section was generated by an AI
// Adapter (agent HOME): lets hg_team/testbench/rc3_wip/probe_rc3.js drive the virtual device
// (../device.js + ../core_api.js + ../home_api.js) instead of the testbench mock:
//   node ../../testbench/rc3_wip/probe_rc3.js --server probe_server.js --port 18081
// Takes the mock options the probe passes (--port, --repo, --time, --ts, --pin, --key) and serves its control routes:
//   GET /__time?set=HH:MM:SS&advance=15s|61s|10m  virtual clock of home_api (loop() keeps running while it advances)
//   POST /__sim {"pir"|"sw"|"clap"|"vol"}          simulated inputs (home.sim)
//   GET /__fs                                       the saved files (configuration, relay states)
//   GET /__reboot                                   home_api setup() again: saved config, staged power-on restore, same key
// Every start uses a fresh temp folder for the saved files. HG_FXSRC from the environment passes through to home_api.
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const http = require('node:http');

const argv = process.argv;
const arg = (n, d) => { const i = argv.indexOf(n); return i > 0 && i + 1 < argv.length ? argv[i + 1] : d; };
const PORT = +arg('--port', 18081);
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'hgprobe-'));
process.env.HG_SAVE = '1';
delete process.env.HG_NO_SAVE;
process.env.HG_CFG_FILE = path.join(tmp, 'hgcfg_wsec.json');
if (arg('--pin')) process.env.HG_PIN = arg('--pin');
if (arg('--key')) process.env.HG_KEY = arg('--key');
if (arg('--ts', '1') !== '1') console.log('note: --ts 0 is not simulated (the virtual clock is always valid)');

const VDIR = path.join(__dirname, '..');
const dev = require(path.join(VDIR, 'device.js'));
const core = require(path.join(VDIR, 'core_api.js'));
const home = require(path.join(VDIR, 'home_api.js'));
const { refuseUpgrade } = require(path.join(VDIR, 'wslib.js'));
if (arg('--time')) home._test.setTime(arg('--time'));

const ms = s => { const m = String(s).match(/^(\d+)(ms|s|m|h)?$/); return m ? +m[1] * ({ ms: 1, s: 1000, m: 60000, h: 3600000 })[m[2] || 's'] : 0; };
const json = (res, code, o) => { res.writeHead(code, { 'Content-Type': 'application/json' }); res.end(JSON.stringify(o)); };

const server = http.createServer((req, res) => {
  const u = new URL(req.url, 'http://x');
  if (u.pathname === '/__time') {
    const set = u.searchParams.get('set');
    if (set) home._test.setTime(home._test.localTime().slice(0, 11) + set);
    if (u.searchParams.has('advance')) home._test.advance(ms(u.searchParams.get('advance')));
    return json(res, 200, { local: home._test.localTime() });
  }
  if (u.pathname === '/__reboot') { home._test.reboot(); return json(res, 200, { ok: true }); }
  if (u.pathname === '/__fs') {
    const files = {};
    for (const [f, v] of Object.entries(home._test.files())) if (v !== undefined) files['/' + path.basename(f)] = v;
    return json(res, 200, { files });
  }
  if (u.pathname === '/__sim' && req.method === 'POST') {
    const ch = [];
    req.on('data', c => ch.push(c));
    req.on('end', () => { let o = {}; try { o = JSON.parse(Buffer.concat(ch).toString() || '{}'); } catch (_) { /* empty */ } json(res, 200, home.sim(o)); });
    return;
  }
  if (home.handle(req, res, dev)) return;
  if (core.handle(req, res, dev)) return;
  res.writeHead(404, { 'Content-Type': 'text/plain' }); res.end('Not found');
});
server.on('upgrade', (req, socket) => {
  if (home.upgrade(req, socket, dev)) return;
  if (core.upgrade(req, socket, dev)) return;
  refuseUpgrade(socket, 404);
});
server.listen(PORT, '127.0.0.1', () => console.log('mock on http://127.0.0.1:' + PORT + '/home (virtualdev, saved files in ' + tmp + ')'));
// AI: end
